+        mocks['ado_' + n] = function(a) { calls.push({ tool: 'ado_' + n, args: a }); return null; };
+    });
+    ['get_ticket', 'search_by_jql', 'post_comment', 'add_label', 'remove_label', 'move_to_status', 'assign_ticket_to',
