    }

    function findPendingBugKey(tcKey) {
        var bugs = findLinkedBugs(tcKey);
        for (var i = 0; i < bugs.length; i++) {
            var status = bugs[i].fields && bugs[i].fields.status && bugs[i].fields.status.name;
            if (status !== statuses.DONE) {
                return bugs[i].key;
